import fs from'node:fs/promises';
import {loadWorld}from'./load-world.mjs';
import {DeepSeekClient}from'./deepseek-client.mjs';
import {economyFoundation}from'../world/design/economy-foundation.mjs';
import {economyGenerationContext}from'./economy-generation-context.mjs';
import {contentHash,economyLoreSchema,validateEconomyLore,loreIssues,auditEconomyLore,assembleEconomy,sampleRows}from'./economy-content.mjs';
const world=await loadWorld(),bones=economyFoundation(world),runId=String(Date.now()),root=`world/drafts/economy/${runId}`;
await fs.mkdir(root,{recursive:true});await fs.mkdir('docs/内容审查',{recursive:true});
const generatorSources=await Promise.all(['tools/draft-economy.mjs','tools/economy-generation-context.mjs','tools/economy-content.mjs'].map(async file=>({file,source:await fs.readFile(file,'utf8')})));
await fs.writeFile(`${root}/generator-sources.json`,JSON.stringify(generatorSources,null,2)+'\n');
await fs.writeFile(`${root}/source.json`,JSON.stringify({runId,sourceWorldHash:contentHash(world),boneHash:contentHash(bones),generatorHash:contentHash(generatorSources),bones},null,2)+'\n');
await fs.writeFile('schemas/economy-lore.schema.json',JSON.stringify(economyLoreSchema,null,2)+'\n');
const client=new DeepSeekClient({budgetYuan:20}),batches=[],allLore=[];
async function draftBatch(index){
 const entities=bones.items.slice(index*50,index*50+50),rows=[],failures=[];
 async function draftOne(offset){
  const requested=[entities[offset]];let passed=false,feedback=null;
  const requestSchema=structuredClone(economyLoreSchema);
  requestSchema.properties.items.minItems=requested.length;requestSchema.properties.items.maxItems=requested.length;
  requestSchema.properties.items.items.properties.id.enum=requested.map(row=>row.id);
  for(let attempt=1;attempt<=3;attempt++){
   try{
    const input={...economyGenerationContext(world,bones,requested[0]),feedback};
    await fs.writeFile(`${root}/input-${index}-${offset}-${attempt}.json`,JSON.stringify(input,null,2)+'\n');
    const response=await client.generate({temperature:.35,max_tokens:1300,tools:[{type:'function',function:{name:'submit_item_lore',description:'只提交这一件器物的id、description、inspection、storage，不复制骨架字段，不增加器物。',parameters:requestSchema}}],tool_choice:{type:'function',function:{name:'submit_item_lore'}},messages:[
      {role:'system',content:`写原创中世纪剑与魔法游戏里的器物说明，作为居民能读懂的商品介绍或术书内容。只补id、description、inspection、storage；其余输入是事实和写作约束，不抄成保证句。description建议110–150字，inspection 60–95字，storage 45–70字；硬限见schema。每件选具体的结构、用途或加工动作，不以同一句起头，不反复讲通用制度。
固定重量、材质、用途、产地和保存期按输入。地点与作者用给定中文名称，编号只写在id字段。storage按storageFacts写指定数字加天字的上限和保管动作，不抄写条件约束。inspection只写外观可见征兆、试用动作和有限判断，不推断所有内部状态。新增的外观细节要与已有材质对应，不能改材质或新增用途、服务与能力。
有readingRequirements时写明读书条件与时间，工序按recipes。普通物品不写读书门槛与保证学成。工作台类别不是工具，workplace给出对应工作地点；工具仅按tools。燃料只供炉火，工序投料另计；涉及烧陶时先干透坯再逐步升火。notes只约束本件，不照抄成规则句。description不反复保证不能得到什么，省去目录索引、自动获物等开发用语。输出严格JSON，仅含这一件器物，schema：${JSON.stringify(requestSchema)}`},
      {role:'user',content:JSON.stringify(input)}]},`economy-${runId}-batch${index}-part${offset}-try${attempt}`);
    const calls=response.choices?.[0]?.message?.tool_calls??[];
    const raw=calls[0]?.function?.arguments??response.choices?.[0]?.message?.content??'';
    await fs.writeFile(`${root}/attempt-${index}-${offset}-${attempt}.json`,JSON.stringify({finishReason:response.choices?.[0]?.finish_reason,raw,calls},null,2)+'\n');
    if(calls.length!==1||calls[0].function.name!=='submit_item_lore')throw new Error('必须且只能提交一次指定说明工具调用');
    const out=JSON.parse(raw);if(!validateEconomyLore(out))throw new Error(JSON.stringify(validateEconomyLore.errors));
    const ids=new Set(out.items.map(row=>row.id));if(ids.size!==requested.length||out.items.length!==requested.length||requested.some(row=>!ids.has(row.id)))throw new Error(`说明编号有遗漏、重复或额外实体；只需${requested.map(row=>row.id).join(',')}，实际收到${out.items.map(row=>row.id).join(',')}`);
    for(const row of out.items){const problems=loreIssues(row,requested.find(bone=>bone.id===row.id));if(problems.length)throw new Error(`${row.id}: ${problems.join('；')}`);}
    rows.push(...out.items);passed=true;break;
   }catch(error){feedback=error.message;failures.push({offset,attempt,error:feedback});console.log(`器物批${index}分组${offset}第${attempt}次失败，原输出保留`);}
  }
  return passed;
 }
 // Independent items are generated concurrently; each has its own three tries.
 // Any exhausted item still rejects the whole batch after in-flight work ends.
 for(let offset=0;offset<entities.length;offset+=4){
   const passes=await Promise.all(Array.from({length:Math.min(4,entities.length-offset)},(_,n)=>draftOne(offset+n)));
   if(passes.some(ok=>!ok))break;
 }
 rows.sort((a,b)=>entities.findIndex(row=>row.id===a.id)-entities.findIndex(row=>row.id===b.id));
 const success=rows.length===entities.length;
 await fs.writeFile(`${root}/batch-${index}.json`,JSON.stringify({index,success,rows,failures,boneHash:contentHash(entities),loreHash:contentHash(rows)},null,2)+'\n');
 batches[index]={index,count:entities.length,success,failures};if(success)allLore.push(...rows);
 console.log(`器物批${index} ${rows.length}/${entities.length}，${success?'结构完成，未人工验收':'待人工处理，整批不得发布'}`);
}
const count=Math.ceil(bones.items.length/50);for(let i=0;i<count;i+=2)await Promise.all(Array.from({length:Math.min(2,count-i)},(_,n)=>draftBatch(i+n)));
allLore.sort((a,b)=>bones.items.findIndex(row=>row.id===a.id)-bones.items.findIndex(row=>row.id===b.id));
let audit=null,candidate=null;
if(allLore.length===bones.items.length){
 audit=auditEconomyLore(allLore,bones);
 try{candidate=assembleEconomy(world,bones,allLore);}catch(error){audit.errors.push({type:'world',message:error.message});audit.ok=false;}
 await fs.writeFile(`${root}/lore.json`,JSON.stringify(allLore,null,2)+'\n');await fs.writeFile(`${root}/audit.json`,JSON.stringify(audit,null,2)+'\n');
 if(candidate)await fs.writeFile(`${root}/candidate-world.json`,JSON.stringify(candidate,null,2)+'\n');
 for(let i=0;i<count;i++){
  const slice=allLore.slice(i*50,i*50+50),seed=20261010+200+i;
  const review={runId,batch:i,count:slice.length,seed,boneHash:contentHash(bones),loreHash:contentHash(allLore),scope:'待人工精读，六项均分至少4且单项不低于3；任一不合格须整批重做',approved:false,
    sample:sampleRows(slice,seed).map(row=>({id:row.id,hash:contentHash(row),scores:null,notes:null}))};
  await fs.writeFile(`docs/内容审查/器物-${runId}-批${i}.json`,JSON.stringify(review,null,2)+'\n');
 }
}
const report={runId,root,scope:'日常经济首批骨架的模型起草，未发布，未人工验收；完整400物品200配方尚未完成',counts:{plannedItems:bones.items.length,plannedRecipes:bones.recipes.length,structuredLore:allLore.length},batches,audit,manualApproved:false,costUpperYuan:client.spent};
if(batches.some(row=>!row.success))await fs.writeFile(`docs/内容审查/器物起草-待处理-${runId}.json`,JSON.stringify({runId,root,scope:'三次失败后停止该批，进入人工处理，不拼接残缺条目发布',batches:batches.filter(row=>!row.success)},null,2)+'\n');
await fs.writeFile(`docs/测试报告/器物起草-${runId}.json`,JSON.stringify(report,null,2)+'\n');
if(batches.some(row=>!row.success)||!audit?.ok)process.exitCode=1;
console.log(JSON.stringify({runId,counts:report.counts,costUpperYuan:client.spent,autoPassed:!!audit?.ok,manualApproved:false}));

// Scope model context to one item: reading requirements are not manufacturing
// requirements, and constraints about one material must not leak into another.
export function economyGenerationContext(world,bones,item){
 const known=new Map(bones.items.map(row=>[row.id,row])),taught=new Set(item.book?.teaches??[]);
 const relevant=bones.recipes.filter(row=>taught.has(row.id)||row.output.item===item.id);
 const recipes=relevant.map(row=>({...row,process:row.process.split('；')[0],
   workplace:{woodworking:'旧磨坊木工工作台',cooking:'青灯酒馆厨房工作台',smithing:'铁匠铺砧台',weaving:'织坊手工工作台',pottery:'白石镇小窑'}[row.workstation],
   materials:row.materials.map(material=>({...material,name:known.get(material.item).name,role:known.get(material.item).tags?.includes('fuel')?'炉火燃料':'加工原料'})),
   byproducts:(row.byproducts??[]).map(material=>({...material,name:known.get(material.item).name,unitWeightKg:known.get(material.item).weight})),
   tools:row.tools.map(id=>({id,name:known.get(id).name})),output:{...row.output,name:known.get(row.output.item).name,unitWeightKg:known.get(row.output.item).weight}}));
 const skillIds=new Set([...item.checkBonus?.skills??[],...relevant.map(row=>row.skill)]);
 const notes=[];
 if(item.book)notes.push('这是工序或技能书。description写明阅读门槛和时间；阅读可在其他地点，不必坐在制作工作台前。学习检定使用智力而非制作手艺，不承诺读完必会。页数未设定，不给出页数。保存期针对这本书，不针对书中成品。');
 else notes.push('这是普通器物或原料，不是书。只讲它的结构、用途、来源和可观察状态，不给它添加识字或读书要求，不讲制作者学会技能的条件。若给了成品配方，只用它核对已有材质和加工方式。');
 const specific={
   item_herb:'这一束药草未辨明具体种类。没有香草、食材或已批准药方身份，description和inspection只写混合束外观、采收、待辨认与保存，不声称可煮汤、喂动物、洗伤口或配治疗药。',
   item_resin:'普通树脂只有黏接来料或引火用途，此处没有具体胶配方，不自行添加炭粉、木屑或骨胶配比。',
   item_rawhide:'生皮毛尚在、仅刮肉脂，未浸灰或鞣制，只是待进一步处理的来料；不添加绷带用途，不把任何地点写成已登记鞣制服务。',
   item_spindle:'这是无轴承的手持木杆加木盘纺锤，杆盘偏摆可检查，但不能仅凭黑色、磨亮或声音确定内部是否腐朽。',
   item_staff:'磨亮、敲响、颜色都是有限的外观线索，不能从单项表征断定心材已坏或完好。',
   item_wax_candle:'实际工序用麻纤维灯芯反复浸挂蜂蜡，不用棉芯，不浇模。',
   item_grain_sack:'保存上限针对布袋本身；袋中食物按各自期限，不把袋子180天改成所有粮食180天。',
   item_book_sew_sack:'这里是针线手工缝袋，只需织坊手工工作台，不是用织机缝合；织机未列为该配方工具。',
   item_oat_flour:'描述食用做法时对应已登记用途：煮粥为水沸后缓入粉并搅锅底，薄饼用厚锅底烙成；不另写冷水下锅粥或热石板烙饼。',
 };
 if(specific[item.id])notes.push(specific[item.id]);
 const locations=new Set([item.origin,...(relevant.length?[...bones.workstations.filter(station=>relevant.some(recipe=>station.kind===recipe.workstation)).map(row=>row.location)]:[])]);
 const input={wantedIds:[item.id],requiredCount:1,item:{...item,use:item.use.split('；')[0]},recipes,
   skills:world.skills.filter(row=>skillIds.has(row.id)).map(({id,name,attribute,stage})=>({id,name,attribute,stage})),
   authors:world.npcs.filter(row=>item.book?.author===row.id).map(({id,name,occupation})=>({id,name,occupation})),
   locations:world.locations.filter(row=>locations.has(row.id)).map(({id,name})=>({id,name})),
   storageFacts:{limitDays:item.shelfLifeDays,condition:item.shelfLifeDays===null?'只写环境、收放与损坏征兆；没有固定存放天数，不能另加最多存多少天':`storage写${item.shelfLifeDays}天；变质可早于上限，但保存条件不会把上限延长`},
   units:'weight以公斤表示一个单件的重量；minutes是分钟，readingMinutes只表示阅读时间。',notes};
 if(item.book)input.readingRequirements={minimumLiteracy:world.rules.books.minimumLiteracy,minutes:item.book.readingMinutes,checkAttribute:'智力',location:null,pageCount:null,
   prerequisites:(item.book.prerequisites??[]).map(row=>({...row,name:world.skills.find(skill=>skill.id===row.skill)?.name}))};
 return input;
}

import Ajv from'ajv';
import {createHash}from'node:crypto';
import {validateWorld}from'./validate-world.mjs';
import {economyFoundation}from'../world/design/economy-foundation.mjs';
export const contentHash=value=>createHash('sha256').update(JSON.stringify(value)).digest('hex');
const text=(minLength,maxLength)=>({type:'string',minLength,maxLength});
export const economyLoreSchema={type:'object',additionalProperties:false,required:['items'],properties:{items:{type:'array',minItems:1,maxItems:4,items:{
 type:'object',additionalProperties:false,required:['id','description','inspection','storage'],properties:{id:text(1,100),description:text(90,190),inspection:text(45,140),storage:text(30,100)}
}}}};
export const validateEconomyLore=new Ajv({strict:true,allErrors:true}).compile(economyLoreSchema);
const makesClaim=(text,pattern)=>text.split(/[，。；！？：\n]/).some(clause=>[...clause.matchAll(new RegExp(pattern,'g'))].some(match=>
 !/(?:不|并非|没有|无法|未|不可|不用).{0,6}$/.test(clause.slice(Math.max(0,match.index-12),match.index))));
function daysNumber(value){
 if(/^\d+$/.test(value))return Number(value);
 const digits={零:0,一:1,二:2,两:2,三:3,四:4,五:5,六:6,七:7,八:8,九:9},units={十:10,百:100,千:1000};let result=0,current=0;
 for(const char of value)if(char in digits)current=digits[char];else if(char in units){result+=(current||1)*units[char];current=0;}else return NaN;
 return result+current;
}
function storageDeadlines(storage){
 const number='(?:[0-9]+|[零一二两三四五六七八九十百千]+)',out=[];
 for(const clause of storage.split(/[，。；！？\n]/)){
   const pattern=new RegExp(`(?:(?:保存|存放|保管)(?:上限|期限|时限)|最多(?:存|放)?|至多|最长|不超过|不宜超过|存|保存|存放|保管)\\s*(${number})天`,'g');
   for(const match of clause.matchAll(pattern)){
     const tail=clause.slice(match.index+match[0].length);
     if(!/(?:上限|期限|时限)/.test(match[0])&&/^(?:需|须|应|要)?(?:取出|拿出|翻出)?(?:复查|检查|翻看|翻动|翻晾|擦拭)/.test(tail))continue;
     out.push(daysNumber(match[1]));
   }
 }
 return out;
}
export function loreIssues(row,bone){
 const text=[row.description,row.inspection,row.storage].join(''),errors=[];
 if(/主持人|提示词|schema|JSON|玩家不能|不要让|系统要求/.test(text))errors.push('世界内说明出现开发规则措辞');
 if(/登记单位|技能编号|目录[^，。；！？]{0,8}(?:固定保存|保存天数|技能等级|索引)|(?:不|不会|不能|并非|未)[^，。；！？]{0,8}(?:赠送|附赠|复制)[^，。；！？]{0,8}(?:成品|粮|线团)|无限(?:供应|灯芯)/.test(text))errors.push('器物说明泄漏目录或游戏保证措辞');
 if(/水泥|塑料|电池|电动|不锈钢|微波|摄氏|冷藏柜|石蜡/.test(text))errors.push('出现未设定的现代物品或技术');
 if(bone?.id==='item_wax_candle'&&makesClaim(row.description,'棉.{0,2}(?:灯芯|芯)|(?:倒入|浇入|浇注).{0,6}模'))errors.push('蜂蜡烛工序与麻芯浸挂配方矛盾');
 if(bone&&!bone.book&&/识字|读满|阅读.{0,6}分钟/.test(row.description))errors.push('普通物品被擅加书本阅读前置');
 if(/否认期限|不能延长|读满\d+分钟(?:就|可|便)[^，。；！？]{0,8}(?:学会|记牢)/.test(text))errors.push('说明抄入写作约束或保证读书学成');
 if(bone?.id==='item_herb'&&makesClaim(text,'煮汤|炖菜|烤肉|喂牲|喂动物|洗伤口'))errors.push('未辨认药草擅作食材或治疗用料');
 if(bone?.id==='item_rawhide'&&makesClaim(text,'绷带|入药|洗伤口'))errors.push('未经处理生皮擅作医疗用料');
 if(bone?.book&&/(?:共|全册|全书|计|约)?(?:[0-9]+|[零一二两三四五六七八九十百千]+)页/.test(row.description))errors.push('书籍未设定页数，不能从阅读分钟推算页数');
 for(const clause of text.split(/[，。；！？：\n]/))for(const match of clause.matchAll(/无限|永不损坏|自动修复|百分之百|保证治愈|凭空|增加\d+点|提升\d+点|魔力加/g)){
    const prefix=clause.slice(Math.max(0,match.index-12),match.index);
    if(!/(?:不|并非|没有|无法|未|不足以).{0,6}$/.test(prefix))errors.push('未在骨架中设定的能力保证');
 }
 if(!bone)errors.push('未知骨架编号');
 else if(Number.isFinite(bone.shelfLifeDays)){
    if(!new RegExp(`(?:^|[^0-9])${bone.shelfLifeDays}天`).test(row.storage??''))errors.push(`保管说明须明确骨架保存上限${bone.shelfLifeDays}天`);
    if(/(?:无|没有|未设|未标|不设|未定)[^，。；！？]{0,10}(?:固定|明确)[^，。；！？]{0,8}(?:保存|保管|期限|天数)|(?:保存|保管)[^，。；！？]{0,8}(?:没有|无|未设)[^，。；！？]{0,5}(?:期限|天数)/.test(row.storage??''))errors.push(`保存期与骨架${bone.shelfLifeDays}天矛盾`);
 }
 if(bone)for(const days of storageDeadlines(row.storage??''))if(days!==bone.shelfLifeDays)errors.push(`擅改保存上限为${days}天，骨架为${bone.shelfLifeDays??'无固定天数'}`);
 return errors;
}
export function assembleEconomy(world,bones,lore){
 const candidate=structuredClone(world),byId=new Map(lore.map(row=>[row.id,row]));
 if(byId.size!==bones.items.length||lore.length!==bones.items.length)throw new Error('经济说明编号遗漏或重复');
 const additions=bones.items.map(bone=>{const row=byId.get(bone.id);if(!row)throw new Error(`缺少说明${bone.id}`);
    if(!validateEconomyLore({items:[row]}))throw new Error(`说明格式不合格${bone.id}`);
    const issues=loreIssues(row,bone);if(issues.length)throw new Error(`${bone.id}: ${issues.join('；')}`);
    return{...bone,...row};});
 const mergeById=(existing,updated)=>{const byId=new Map(updated.map(row=>[row.id,row]));
    return[...existing.map(row=>byId.get(row.id)??row),...updated.filter(row=>!existing.some(old=>old.id===row.id))];};
 candidate.items=mergeById(candidate.items,additions);
 candidate.recipes=mergeById(candidate.recipes,structuredClone(bones.recipes));
 for(const station of bones.workstations){const location=candidate.locations.find(row=>row.id===station.location);if(!location)throw new Error('工坊位置不在世界中');
    const {location:ignored,...record}=station;location.workstations??=[];
    const index=location.workstations.findIndex(row=>row.id===record.id);
    if(index<0)location.workstations.push(record);else location.workstations[index]=record;
 }
 const validation=validateWorld(candidate,{stage:'engine'});if(!validation.ok)throw new Error(validation.errors.join('\n'));
 return candidate;
}
const corpus=row=>[row.description,row.inspection,row.storage].join('');
const grams=value=>{const clean=value.replace(/[^\p{L}]/gu,'');return new Set(Array.from({length:Math.max(0,clean.length-1)},(_,i)=>clean.slice(i,i+2)));};
const similarity=(a,b)=>{let n=0;for(const gram of a)if(b.has(gram))n++;return n/(a.size+b.size-n||1);};
export function auditEconomyLore(lore,bones){
 const errors=[],warnings=[],sets=lore.map(row=>grams(corpus(row))),byId=new Map(bones.items.map(row=>[row.id,row]));
 if(new Set(lore.map(row=>row.id)).size!==lore.length)errors.push({type:'duplicate'});
 for(const row of lore){if(!validateEconomyLore({items:[row]}))errors.push({id:row.id,type:'schema',errors:structuredClone(validateEconomyLore.errors)});
    for(const message of loreIssues(row,byId.get(row.id)))errors.push({id:row.id,type:'lore',message});
 }
 let maximumSimilarity=0;
